@Mod("monmod")
public class MonMod {
    public static final String MOD_ID = "monmod";

    public MonMod() {
        IEventBus modBus = FMLJavaModLoadingContext.get().getModEventBus();
        ModItems.ITEMS.register(modBus);
        ModBlocks.BLOCKS.register(modBus);
        ModEffects.EFFECTS.register(modBus);
        modBus.addListener(this::setup);
    }

    private void setup(FMLCommonSetupEvent event) {
        // initialisation thread-safe :
        event.enqueueWork(() -> { });
    }
}

new ResourceLocation("monmod", "nom_objet")
// → "monmod:nom_objet"
// Depuis 1.21 / NeoForge : ResourceLocation.fromNamespaceAndPath("monmod","nom")

@Mod.EventBusSubscriber(modid = MOD_ID, bus = Bus.FORGE)
public class ForgeEvents {
    @SubscribeEvent
    public static void onEvent(TypeEvenement event) { ... }
}

@Mod.EventBusSubscriber(modid = MOD_ID, bus = Bus.MOD)
public class ModEvents {
    @SubscribeEvent
    public static void onSetup(FMLCommonSetupEvent event) { ... }
}

// Dans ModItems.java :
public static final DeferredRegister<Item> ITEMS =
    DeferredRegister.create(ForgeRegistries.ITEMS, MOD_ID);

public static final RegistryObject<Item> RUBY =
    ITEMS.register("ruby",
        () -> new Item(new Item.Properties()));

public class MonItem extends Item {
    public MonItem() {
        super(new Item.Properties().stacksTo(1));
    }

    @Override
    public InteractionResultHolder<ItemStack> use(
            Level level, Player player, InteractionHand hand) {
        ItemStack stack = player.getItemInHand(hand);
        if (!level.isClientSide()) {
            // logique serveur
        }
        return InteractionResultHolder.success(stack);
    }
}

// Dans ModBlocks.java :
public static final DeferredRegister<Block> BLOCKS =
    DeferredRegister.create(ForgeRegistries.BLOCKS, MOD_ID);

public static final RegistryObject<Block> RUBY_BLOCK =
    BLOCKS.register("ruby_block", () ->
        new Block(BlockBehaviour.Properties.of()
            .strength(3.0f, 6.0f)
            .requiresCorrectToolForDrops()));

// Dans ModItems.java, après l'enregistrement du bloc :
public static final RegistryObject<Item> RUBY_BLOCK_ITEM =
    ITEMS.register("ruby_block",
        () -> new BlockItem(ModBlocks.RUBY_BLOCK.get(),
                            new Item.Properties()));

public class MonBloc extends Block {
    public MonBloc() {
        super(BlockBehaviour.Properties.of().strength(2.0f));
    }

    @Override
    public InteractionResult use(BlockState state, Level level,
            BlockPos pos, Player player, InteractionHand hand,
            BlockHitResult hit) {
        if (!level.isClientSide()) { ... }
        return InteractionResult.SUCCESS;
    }
}

// Dans ModEffects.java :
public static final DeferredRegister<MobEffect> EFFECTS =
    DeferredRegister.create(ForgeRegistries.MOB_EFFECTS, MOD_ID);

public static final RegistryObject<MobEffect> MON_EFFET =
    EFFECTS.register("mon_effet", MonEffet::new);

// Dans ModSounds.java :
public static final DeferredRegister<SoundEvent> SOUND_EVENTS =
    DeferredRegister.create(ForgeRegistries.SOUND_EVENTS, MOD_ID);

public static final RegistryObject<SoundEvent> MON_SON =
    SOUND_EVENTS.register("mon_son",
        () -> SoundEvent.createVariableRangeEvent(
                  new ResourceLocation(MOD_ID, "mon_son")));

// Dans ModMenuTypes.java :
public static final DeferredRegister<MenuType<?>> MENUS =
    DeferredRegister.create(ForgeRegistries.MENU_TYPES, MOD_ID);

public static final RegistryObject<MenuType<MonMenu>> MON_MENU =
    MENUS.register("mon_menu",
        () -> IForgeMenuType.create(
                  (windowId, inv, data) -> new MonMenu(windowId, inv, data)));

// Dans ModEntityTypes.java :
public static final DeferredRegister<EntityType<?>> ENTITY_TYPES =
    DeferredRegister.create(ForgeRegistries.ENTITY_TYPES, MOD_ID);

public static final RegistryObject<EntityType<MonEntity>> MON_ENTITY =
    ENTITY_TYPES.register("mon_entity",
        () -> EntityType.Builder.<MonEntity>of(MonEntity::new, MobCategory.MONSTER)
                .sized(0.6f, 1.95f)
                .build("mon_entity"));

@SubscribeEvent
public static void onFMLCommonSetup(FMLCommonSetupEvent event) {
    event.enqueueWork(() -> {
        // code thread-safe : enregistrement de caps, dispense, etc.
    });
}

@SubscribeEvent
public static void onClientSetup(FMLClientSetupEvent event) {
    event.enqueueWork(() -> {
        // enregistrement renderer entité, blit shader, etc. (CLIENT uniquement)
    });
}

@SubscribeEvent
public static void onRegisterCreativeTabs(BuildCreativeModeTabContentsEvent event) {
    if (event.getTabKey() == CreativeModeTabs.INGREDIENTS) {
        event.accept(ModItems.RUBY.get());
    }
}
